                var raEl = document.getElementById('riskAdjustSelect');
                if (eqEl) decisions.equityBasis = eqEl.value;
                if (dtEl) decisions.debtCost = dtEl.value;
                if (raEl) decisions.riskAdjust = raEl.value;
                return true;
            }

            if (round === 2) {
                var opps = [];
                var ids = ['oppA','oppB','oppC','oppD','oppE'];
                for (var i = 0; i < ids.length; i++) {
                    var el = document.getElementById(ids[i]);
                    if (el && el.checked) opps.push(el.value);
                }
                decisions.selectedOpps = opps;
                var rmEl = document.getElementById('rankingMethodSelect');
                var scEl = document.getElementById('scenarioSelect');
                if (rmEl) decisions.rankingMethod = rmEl.value;
                if (scEl) decisions.scenarioAnalysis = scEl.value;
                if (opps.length === 0) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_no_investment'), 'warning'
                    );
                    return false;
                }
                return true;
            }

            if (round === 3) {
                var ic = document.getElementById('internalCashInput');
                var nb = document.getElementById('newBondInput');
                var rv = document.getElementById('revolverInput');
                var cv = document.getElementById('convertibleInput');
                var eq = document.getElementById('equityInput');
                decisions.internalCash = ic ? parseFloat(ic.value) || 0 : 0;
                decisions.newBond = nb ? parseFloat(nb.value) || 0 : 0;
                decisions.revolver = rv ? parseFloat(rv.value) || 0 : 0;
                decisions.convertible = cv ? parseFloat(cv.value) || 0 : 0;
                decisions.equityIssue = eq ? parseFloat(eq.value) || 0 : 0;

                var totalFin = decisions.internalCash + decisions.newBond + decisions.revolver + decisions.convertible + decisions.equityIssue;
                var needed = st.domainState.totalInvestment;
                if (totalFin < needed) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_financing_short') + ' $' + needed + 'M ' + window.mySimulation.t('warn_needed') + ', $' + totalFin.toFixed(1) + 'M ' + window.mySimulation.t('warn_provided') + '.', 'warning'
                    );
                    return false;
                }
                if (decisions.internalCash > 40) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('warn_cash_limit'), 'warning'
                    );
                    return false;
                }
                return true;
            }

            if (round === 4) {
                var wr = document.getElementById('wcReceivables');
                var wi = document.getElementById('wcInventory');
                var wf = document.getElementById('wcFactoring');
                var dc = document.getElementById('disclosureCheck');
                decisions.wcRecv = wr ? wr.checked : false;
                decisions.wcInv = wi ? wi.checked : false;
                decisions.wcFact = wf ? wf.checked : false;
                decisions.disclosure = dc ? dc.checked : false;
                return true;
            }

            return true;
        }

        calculateResults(state) {
            var round = state.currentPeriod;
            var d = state.decisions;
            var ds = state.domainState;
            var score = 0;
            var roundName = '';
            var feedback = '';
            var _t = function(k) { try { return window.mySimulation.t(k); } catch (e) { return k; } };
            var _fill = function(tpl, map) {
                var out = tpl;
                for (var mk in map) { out = out.split('{' + mk + '}').join(String(map[mk])); }
                return out;
            };

            if (round === 1) {
                roundName = _t('rname_r1');
                var correct = 0;
                if (d.equityBasis === 'market') correct++;
                if (d.debtCost === 'ytm') correct++;
                if (d.riskAdjust === 'yes') correct++;

                var eqV = d.equityBasis === 'market' ? 220 : 95;
                var dV = 87;
                var tV = eqV + dV;
                var ke = 0.051 + 1.15 * 0.074;
                var kd = d.debtCost === 'ytm' ? 0.078 : 0.092;
                var wacc = (eqV / tV) * ke + (dV / tV) * kd * (1 - 0.35);
                ds.wacc = Math.round(wacc * 1000) / 10;
                ds.waccCorrect = correct;

                if (correct === 3) score = 20;
                else if (correct === 2) score = 13;
                else if (correct === 1) score = 7;
                else score = 0;

                feedback = _fill(_t('feedback_r1'), { correct: correct, wacc: ds.wacc });
                ds.eventMsg = window.mySimulation.t('event_tax_reform');
            }

            if (round === 2) {
                roundName = _t('rname_r2');
                var opps = d.selectedOpps || [];
                var totalCost = 0;
                var self = this;
                for (var i = 0; i < opps.length; i++) {
                    var opp = self.OPPS[opps[i]];
                    if (opp) totalCost += opp.cost;
                }
                ds.selectedOpps = opps.slice();
                ds.totalInvestment = totalCost;

                score = 0;
                if (d.rankingMethod === 'npv') score += 10;
                if (d.scenarioAnalysis === 'weighted') score += 8;
                if (opps.indexOf('B') >= 0) score += 4;
                if (totalCost <= 65 && totalCost > 0) score += 3;
                score = Math.min(score, 25);

                feedback = _fill(_t('feedback_r2'), { opps: opps.join(', '), total: totalCost, method: d.rankingMethod.toUpperCase() });
                if (opps.indexOf('B') >= 0) {
                    ds.eventMsg = window.mySimulation.t('event_rival_bid');
                } else {
                    ds.eventMsg = '';
                }
            }

            if (round === 3) {
                roundName = _t('rname_r3');
                var newDebt = d.newBond + d.revolver + d.convertible;
                var debtPaydown = 0;
                if (ds.selectedOpps.indexOf('C') >= 0) debtPaydown = 30;

                var pfNetDebt = 87 + newDebt - debtPaydown;
                var pfEBITDA = 31;
                var ndRatio = pfNetDebt / pfEBITDA;

                var curInterest = 7.49;
                if (debtPaydown > 0) curInterest -= 2.76;
                var newInterest = d.newBond * 0.071 + d.revolver * 0.073 + d.convertible * 0.058;
                var totalInterest = curInterest + newInterest;
                var intCov = totalInterest > 0 ? 27 / totalInterest : 99;

                ds.netDebtEbitda = Math.round(ndRatio * 10) / 10;
                ds.interestCoverage = Math.round(intCov * 10) / 10;

                var downgraded = ndRatio > 3.5 || intCov < 3.0;
                ds.creditRating = downgraded ? 'BB+' : 'BBB-';

                score = 0;
                var totalFin = d.internalCash + d.newBond + d.revolver + d.convertible + d.equityIssue;
                if (totalFin >= ds.totalInvestment) score += 3;
                if (!downgraded) score += 12;
                if (newDebt >= 5 && newDebt <= 20) score += 5;
                else if (newDebt > 0 && newDebt < 5) score += 3;
                else if (newDebt > 20 && !downgraded) score += 2;
                if (d.internalCash >= 15) score += 5;
                else if (d.internalCash >= 5) score += 3;
                score = Math.min(score, 25);

                feedback = _fill(_t('feedback_r3'), { nd: ds.netDebtEbitda, cov: ds.interestCoverage, rating: ds.creditRating });
                if (ds.selectedOpps.indexOf('B') >= 0) {
                    ds.eventMsg = window.mySimulation.t('event_cfo_resign');
                } else {
                    ds.eventMsg = '';
                }
            }

            if (round === 4) {
                roundName = _t('rname_r4');
                var wcTotal = 0;
                var interventions = 0;
                if (d.wcRecv) { wcTotal += 4.2; interventions++; }
                if (d.wcInv) { wcTotal += 3.8; interventions++; }
                if (d.wcFact) { wcTotal += 4.0; interventions++; }
                ds.wcReleased = Math.round(wcTotal * 10) / 10;
                ds.disclosed = d.disclosure;

                score = 0;
                score += Math.min(Math.round(wcTotal / 12.0 * 15), 15);
                if (d.wcFact && d.disclosure) score += 10;
                else if (!d.wcFact) score += 7;
                if (interventions >= 2) score += 5;
                else if (interventions >= 1) score += 2;
                score = Math.min(score, 30);

                ds.cash = Math.round((40 - Math.min(ds.totalInvestment, 40) + wcTotal) * 10) / 10;
                feedback = _fill(_t('feedback_r4'), { wc: ds.wcReleased, n: interventions, disclosed: _t(d.disclosure ? 'yes_label' : 'no_label') });
                ds.eventMsg = '';
            }

            ds.totalScore += score;
            ds.scoreHistory.push(score);
            ds.roundLabels.push(roundName);

            // overallScore mirrors getPerformanceSummary: totalScore already sums the four
            // round maxes (20+25+25+30) to 100, so the running cumulative score is 0-100 as is
            var overallScore = Math.max(0, Math.min(100, Math.round(ds.totalScore)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            var adapter = this;
            var nextPeriod = round + 1;
            setTimeout(function() {
                if (nextPeriod <= adapter.ROUNDS.length) {
                    adapter._updateBriefing({ currentPeriod: nextPeriod, domainState: ds });
                }
            }, 500);

            return {
                period: state.currentPeriod,
                roundName: roundName,
                score: score,
                totalScore: ds.totalScore,
                feedback: feedback,
                creditRating: ds.creditRating,
                wacc: ds.wacc
            };
        }

