        getPerformanceSummary(history) {
            if (!history.length) return {};
            var total = 0;
            for (var i = 0; i < history.length; i++) {
                total += (history[i].results ? history[i].results.score || 0 : 0);
            }
            var pct = Math.round(total / 100 * 100);
            var _t = function(k){ try { return window.mySimulation.t(k); } catch(e){ return k; } };
            var performance = _t('perf_insufficient');
            if (pct >= 90) performance = _t('perf_excellent');
            else if (pct >= 70) performance = _t('perf_competent');
            else if (pct >= 50) performance = _t('perf_developing');

            var insights = [];
            if (history.length >= 1 && history[0].results) {
                insights.push(_t(history[0].results.score >= 18 ? 'insight_r1_strong' : 'insight_r1_weak'));
            }
            if (history.length >= 2 && history[1].results) {
                insights.push(_t(history[1].results.score >= 20 ? 'insight_r2_strong' : 'insight_r2_weak'));
            }
            if (history.length >= 3 && history[2].results) {
                insights.push(_t(history[2].results.score >= 18 ? 'insight_r3_strong' : 'insight_r3_weak'));
            }
            if (history.length >= 4 && history[3].results) {
                insights.push(_t(history[3].results.score >= 25 ? 'insight_r4_strong' : 'insight_r4_weak'));
            }

            return {
                totalScore: total,
                maxScore: 100,
                percentage: pct,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            var ds = state.domainState;
            if (ds.eventMsg && ds.eventMsg.length > 0) {
                return ds.eventMsg;
            }
            if (results && results.score !== undefined) {
                var maxForRound = [20, 25, 25, 30];
                var idx = state.currentPeriod - 1;
                if (idx >= 0 && idx < 4 && results.score < maxForRound[idx] * 0.4) {
                    return window.mySimulation.t('hint_review');
                }
            }
            return null;
        }

