        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var roundKey = 'round' + (idx + 1);

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) titleEl.innerHTML = window.mySimulation ? window.mySimulation.t(roundKey + '_title') : round.title;

            var textEl = document.getElementById('briefingText');
            if (textEl) {
                if (idx === 2 && state.domainState) {
                    var t = state.domainState.totalInvestment || 0;
                    textEl.innerHTML = window.mySimulation
                        ? window.mySimulation.t('fin_need_prefix') + '<strong>$' + t + 'M</strong>' + window.mySimulation.t('fin_need_suffix')
                        : 'Your selected investments require <strong>$' + t + 'M</strong> in total financing. Design a mix from the sources below.';
                } else {
                    textEl.innerHTML = window.mySimulation ? window.mySimulation.t(roundKey + '_brief') : round.brief;
                }
            }

            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var p = 0; p < panels.length; p++) {
                var el = document.getElementById(panels[p]);
                if (el) el.style.display = panels[p] === round.panel ? 'block' : 'none';
            }

            if (idx === 2) {
                this._updateCreditModel();
                var needEl = document.getElementById('financingNeedText');
                if (needEl && state.domainState) {
                    var amt = state.domainState.totalInvestment || 0;
                    if (window.mySimulation) {
                        needEl.innerHTML = window.mySimulation.t('fin_need_prefix') + '<strong>$' + amt + 'M</strong>' + window.mySimulation.t('fin_need_suffix');
                    }
                }
            }
        }

        _updateRiskAdjustOptions() {
            var raSel = document.getElementById('riskAdjustSelect');
            if (!raSel || !window.mySimulation) return;
            for (var i = 0; i < raSel.options.length; i++) {
                var opt = raSel.options[i];
                if (opt.value === 'no') opt.textContent = window.mySimulation.t('risk_adjust_no');
                else if (opt.value === 'yes') opt.textContent = window.mySimulation.t('risk_adjust_yes');
            }
        }

        _setupListeners() {
            var self = this;

            var eqSel = document.getElementById('equityBasisSelect');
            var dtSel = document.getElementById('debtCostSelect');
            var raSel = document.getElementById('riskAdjustSelect');
            if (eqSel) eqSel.addEventListener('change', function() { self._updateWACCPreview(); });
            if (dtSel) dtSel.addEventListener('change', function() { self._updateWACCPreview(); });
            if (raSel) raSel.addEventListener('change', function() { self._updateWACCPreview(); });
            self._updateWACCPreview();

            var oppIds = ['oppA','oppB','oppC','oppD','oppE'];
            for (var o = 0; o < oppIds.length; o++) {
                var oel = document.getElementById(oppIds[o]);
                if (oel) oel.addEventListener('change', function() { self._updateInvestmentTotal(); });
            }

            var finIds = ['internalCashInput','newBondInput','revolverInput','convertibleInput','equityInput'];
            for (var f = 0; f < finIds.length; f++) {
                var fel = document.getElementById(finIds[f]);
                if (fel) fel.addEventListener('input', function() { self._updateCreditModel(); });
            }

            var wcr = document.getElementById('wcReceivables');
            var wci = document.getElementById('wcInventory');
            var wcf = document.getElementById('wcFactoring');
            if (wcr) wcr.addEventListener('change', function() { self._updateWCTotal(); });
            if (wci) wci.addEventListener('change', function() { self._updateWCTotal(); });
            if (wcf) wcf.addEventListener('change', function() {
                var dg = document.getElementById('disclosureGroup');
                if (dg) dg.style.display = wcf.checked ? 'block' : 'none';
                self._updateWCTotal();
            });
        }

        _updateWACCPreview() {
            var eqSel = document.getElementById('equityBasisSelect');
            var dtSel = document.getElementById('debtCostSelect');
            if (!eqSel || !dtSel) return;
            var eqV = eqSel.value === 'market' ? 220 : 95;
            var dV = 87;
            var tV = eqV + dV;
            var ke = 0.051 + 1.15 * 0.074;
            var kd = dtSel.value === 'ytm' ? 0.078 : 0.092;
            var wacc = (eqV / tV) * ke + (dV / tV) * kd * (1 - 0.35);
            var el = document.getElementById('waccPreview');
            if (el) el.textContent = (wacc * 100).toFixed(1) + '%';
        }

        _updateInvestmentTotal() {
            var total = 0;
            var ids = ['oppA','oppB','oppC','oppD','oppE'];
            for (var i = 0; i < ids.length; i++) {
                var el = document.getElementById(ids[i]);
                if (el && el.checked && this.OPPS[el.value]) {
                    total += this.OPPS[el.value].cost;
                }
            }
            var disp = document.getElementById('totalInvestment');
            if (disp) disp.textContent = '$' + total + 'M';
        }

        _updateCreditModel() {
            var ds = window.mySimulation ? window.mySimulation.state.domainState : null;
            if (!ds) return;

            var nb = parseFloat((document.getElementById('newBondInput') || {}).value) || 0;
            var rv = parseFloat((document.getElementById('revolverInput') || {}).value) || 0;
            var cv = parseFloat((document.getElementById('convertibleInput') || {}).value) || 0;

            var newDebt = nb + rv + cv;
            var debtPaydown = (ds.selectedOpps && ds.selectedOpps.indexOf('C') >= 0) ? 30 : 0;
            var pfNetDebt = 87 + newDebt - debtPaydown;
            var pfEBITDA = 31;
            var ndRatio = pfNetDebt / pfEBITDA;

            var curInt = 7.49;
            if (debtPaydown > 0) curInt -= 2.76;
            var newInt = nb * 0.071 + rv * 0.073 + cv * 0.058;
            var totalInt = curInt + newInt;
            var intCov = totalInt > 0 ? 27 / totalInt : 99;

            var ndEl = document.getElementById('ndEbitdaDisplay');
            var icEl = document.getElementById('intCoverageDisplay');
            var ndSt = document.getElementById('ndEbitdaStatus');
            var icSt = document.getElementById('intCoverageStatus');
            var pfr = document.getElementById('proFormaRating');

            if (ndEl) ndEl.textContent = ndRatio.toFixed(1) + 'x';
            if (icEl) icEl.textContent = (isFinite(intCov) ? intCov.toFixed(1) : '--') + 'x';

            var ndOk = ndRatio <= 3.5;
            var icOk = isFinite(intCov) && intCov >= 3.0;
            var _tcm = function(k, d) { try { return window.mySimulation.t(k); } catch (e) { return d; } };

            if (ndSt) {
                ndSt.textContent = ndOk ? _tcm('status_ok', 'OK') : _tcm('status_breach', 'BREACH');
                ndSt.className = ndOk ? 'cfo-sim-status-ok' : 'cfo-sim-status-breach';
            }
            if (icSt) {
                icSt.textContent = icOk ? _tcm('status_ok', 'OK') : _tcm('status_breach', 'BREACH');
                icSt.className = icOk ? 'cfo-sim-status-ok' : 'cfo-sim-status-breach';
            }
            if (pfr) {
                var ok = ndOk && icOk;
                pfr.textContent = ok ? 'BBB-' : 'BB+ ' + _tcm('rating_downgrade_suffix', '(DOWNGRADE)');
                pfr.style.color = ok ? '#276749' : '#9b2c2c';
            }
        }

        _updateWCTotal() {
            var total = 0;
            var wr = document.getElementById('wcReceivables');
            var wi = document.getElementById('wcInventory');
            var wf = document.getElementById('wcFactoring');
            if (wr && wr.checked) total += 4.2;
            if (wi && wi.checked) total += 3.8;
            if (wf && wf.checked) total += 4.0;
            var el = document.getElementById('wcReleasedDisplay');
            if (el) el.textContent = '$' + total.toFixed(1) + 'M';
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CFOCommandAdapter(), {
            simulationType: 'cfo_command_210',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    });

